-- cortex.read_scopes: what a person chose to read from a design's database (decision read-scope): everything, or the kinds of object and the objects listed under it; a choice is never changed, a new choice is a new row, so every read names the choice it ran with. Owner: cortex.
CREATE TABLE cortex.read_scopes (
  id          BIGINT NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,                                  -- issued by the database
  design      UUID NOT NULL REFERENCES cortex.designs (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,  -- the design it belongs to
  everything  BOOLEAN NOT NULL,                                                                              -- true for every object of every kind the engine reads at the server's version; false for only the kinds and objects listed under it
  made_by     TEXT NOT NULL CHECK (length(made_by) >= 1),                                                    -- who chose it, as the app names them
  made_at     TIMESTAMPTZ NOT NULL DEFAULT now(),                                                            -- when it was chosen
  UNIQUE (design, id)
);

COMMENT ON TABLE cortex.read_scopes IS 'what a person chose to read from a design''s database (decision read-scope): everything, or the kinds of object and the objects listed under it; a choice is never changed, a new choice is a new row, so every read names the choice it ran with.';
COMMENT ON COLUMN cortex.read_scopes.id IS 'issued by the database';
COMMENT ON COLUMN cortex.read_scopes.design IS 'the design it belongs to';
COMMENT ON COLUMN cortex.read_scopes.everything IS 'true for every object of every kind the engine reads at the server''s version; false for only the kinds and objects listed under it';
COMMENT ON COLUMN cortex.read_scopes.made_by IS 'who chose it, as the app names them';
COMMENT ON COLUMN cortex.read_scopes.made_at IS 'when it was chosen';
